 let disabled=['PEI','PEEK'].includes(f);let specialist=['PPS','PPE','PPA','PVDF'].includes(f)||v==='emi'||/Space Grade|Flame Retardant/.test(name);let enclosed=['ABS','ASA','PA','PA11','PA12','PA6','PA612','PC'].includes(f)||f==='CPE';let status=disabled?'not_verified_for_current_fleet':specialist?'specialist_review_required':enclosed?'enclosure_and_process_validation':'material_and_geometry_validation';
