 let props=[];if(p?.id.startsWith('fiberlogy-')){const section=p.text.split('Technical Specifications')[1]?.split('Colors')[0]?.split('Downloads')[0]||'';const rx=/(Density|(?:Heat deflection temperature|Heat Distortion Temperature)[^:]*|Tensile strength[^:]*|Tensile modulus[^:]*|Flexural modulus|Flexural strength|(?:Izod|Charpy) impact strength[^:]*|(?:Vicat|Glass transition) [^:]*|Elongation[^:]*|(?:Volume|Surface) resistivity)\s*:\s*(.*?)(?=\s+(?:Density|Heat |Tensile |Flexural |Izod |Charpy |Vicat |Glass |Elongation|Volume |Surface )|$)/gi;for(const m of section.matchAll(rx))props.push({property:m[1],value:m[2].trim(),source_url:p.url,source_type:'manufacturer_webpage',test_state:'not_established_from_webpage'});}
