for(const [name,f,v,re] of poly){let d=manifest.find(m=>m.status==='downloaded'&&m.kind==='pdf'&&re.test(m.path));if(d)add(name,f,v,'Polymaker',null,re);}
for(const [name,f,v,re] of fill){let d=manifest.find(m=>m.status==='downloaded'&&m.kind==='pdf'&&re.test(m.path));if(d){let p=pages.find(p=>p.id.startsWith('fillamentum-')&&p.id!=='fillamentum-data'&&p.text.toLowerCase().includes(name.toLowerCase()));add(name,f,v,'Fillamentum',p,re);}}
// Include original PDF links found inside downloaded ZIP packages in each grade record.
async function files(d){let a=[];for(const e of await fs.readdir(d,{withFileTypes:true})){let p=path.join(d,e.name);if(e.isDirectory())a.push(...await files(p));else a.push(p);}return a;}
const allFiles=await files(path.join(root,'06_DATASHEETS'));
for(const m of records){if(m.brand==='Prusament'&&m.manufacturer_tds_status!=='downloaded'){let p=pages.find(p=>p.url===m.source_url);let z=manifest.filter(z=>z.kind==='zip'&&z.status==='downloaded'&&z.source_page===p?.url);for(const item of z){let base=path.join(root,path.dirname(item.path),path.basename(item.path,'.zip')+'_extracted');for(const f of allFiles.filter(f=>f.startsWith(base)&&/\.pdf$/i.test(f)&&!/sds|msds/i.test(path.basename(f)))){m.datasheets.push({path:path.relative(root,f).replaceAll('\\','/'),url:item.url,source_page:m.source_url,document_type:'TDS',status:'downloaded_from_manufacturer_zip'});m.manufacturer_tds_status='downloaded';}}}}
records.sort((a,b)=>a.name.localeCompare(b.name,'en',{sensitivity:'base'}));
function drawing(m){let type=m.drawing_type;const title=m.application_examples[0].title;let s=[];s.push(`<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900" viewBox="0 0 1400 900"><rect width="1400" height="900" fill="#f8fbff"/><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#dce7f2" stroke-width=".7"/></pattern><marker id="arrow" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto-start-reverse"><path d="M0 0L8 4L0 8Z" fill="#276087"/></marker></defs><rect x="30" y="30" width="1340" height="840" fill="url(#grid)" stroke="#193d61" stroke-width="2"/><g font-family="Arial,sans-serif" fill="#193d61"><text x="65" y="80" font-size="29">EVA PRINT SRL | ${esc(title.toUpperCase())}</text><text x="65" y="115" font-size="19">Material study: ${esc(m.name)} | Illustrative concept, not a manufacturing release</text><text x="65" y="172" font-size="18">FRONT VIEW</text><text x="520" y="172" font-size="18">TOP VIEW</text><text x="980" y="172" font-size="18">SIDE VIEW</text></g>`);
 let geom='';let mm=120,h=80;
 if(type==='ring'||type==='gear'){mm=100;h=100;geom=`<circle cx="235" cy="350" r="145"/><circle cx="235" cy="350" r="67"/><path d="M70 350H400M235 185V515" stroke-dasharray="10 5" stroke-width="1.2"/>`;if(type==='gear'){for(let i=0;i<16;i++){let a=i*Math.PI/8;geom+=`<path d="M${235+145*Math.cos(a)} ${350+145*Math.sin(a)}L${235+165*Math.cos(a)} ${350+165*Math.sin(a)}"/>`;}}}
 else if(type==='vase'){geom='<path d="M120 490L110 290Q120 200 235 200Q350 200 360 290L350 490Z"/><ellipse cx="235" cy="215" rx="115" ry="25"/><path d="M120 300Q235 355 360 300M120 390Q235 445 360 390"/>';mm=100;h=120;}
 else if(type==='architecture'){geom='<path d="M85 490V330H155V250H255V190H355V490ZM155 330V490M255 250V490"/><path d="M175 280H220V310H175ZM175 350H220V380H175ZM280 220H325V250H280ZM280 290H325V320H280Z"/>';}
 else if(type==='support'){geom='<path d="M85 490V280H385V350H310V420H235V490Z"/><path d="M90 485L230 345M125 490L270 345M165 490L310 345M205 490L310 385" stroke-dasharray="7 5" stroke-width="1.5"/>';}
 else if(type==='bracket'){geom='<path d="M85 490V220H150V415H385V490Z"/><circle cx="118" cy="270" r="14"/><circle cx="118" cy="355" r="14"/><circle cx="220" cy="452" r="14"/><circle cx="320" cy="452" r="14"/><path d="M150 340L260 415H150Z"/>';}
 else{geom='<rect x="85" y="230" width="300" height="260" rx="12"/><rect x="112" y="258" width="246" height="204" rx="5"/><circle cx="100" cy="245" r="7"/><circle cx="370" cy="245" r="7"/><circle cx="100" cy="475" r="7"/><circle cx="370" cy="475" r="7"/>';}
 s.push(`<g stroke="#193d61" stroke-width="3" fill="none">${geom}<rect x="520" y="240" width="300" height="210"/><path d="M540 260H800V430H540ZM540 340H800"/><rect x="980" y="240" width="200" height="250"/><path d="M1000 260H1160V470H1000Z" stroke-dasharray="8 5"/></g><g stroke="#276087" stroke-width="1.5" fill="none"><path d="M85 500V560M385 500V560M85 545H385" marker-start="url(#arrow)" marker-end="url(#arrow)"/><path d="M55 230H75M55 490H75M60 230V490" marker-start="url(#arrow)" marker-end="url(#arrow)"/></g><g font-family="Arial,sans-serif" fill="#193d61"><text x="210" y="538" font-size="18">${mm} mm*</text><text x="38" y="385" font-size="18" transform="rotate(-90 38 385)">${h} mm*</text><text x="70" y="630" font-size="19">DESIGN NOTES</text><text x="70" y="660" font-size="17">*Indicative envelope only. Geometry is schematic and not to scale.</text><text x="70" y="690" font-size="17">Define exact CAD geometry, tolerances, wall thickness and print orientation before manufacture.</text><text x="70" y="720" font-size="17">Material selection depends on load, environment, grade data and agreed acceptance criteria.</text></g><path d="M30 760H1370M920 760V870" stroke="#193d61" stroke-width="2"/><g font-family="Arial,sans-serif" fill="#193d61"><text x="55" y="798" font-size="21">EVA PRINT SRL | Original illustrative drawing</text><text x="55" y="834" font-size="17">print@eva-org.com | ${esc(m.id)}</text><text x="945" y="792" font-size="17">Sheet 1 / 1 | Units: mm</text><text x="945" y="822" font-size="17">Revision: A | 2026-10-02</text><text x="945" y="852" font-size="17">Status: CONCEPT ONLY</text></g></svg>`);return s.join('');}
function dxf(m){let p=[];const pair=(a,b)=>p.push(String(a),String(b));pair(0,'SECTION');pair(2,'HEADER');pair(9,'$ACADVER');pair(1,'AC1015');pair(9,'$INSUNITS');pair(70,4);pair(0,'ENDSEC');pair(0,'SECTION');pair(2,'ENTITIES');const line=(x,y,x2,y2,layer='OUTLINE')=>{pair(0,'LINE');pair(8,layer);pair(10,x);pair(20,y);pair(30,0);pair(11,x2);pair(21,y2);pair(31,0);};const text=(x,y,s,h=4)=>{pair(0,'TEXT');pair(8,'ANNOTATION');pair(10,x);pair(20,y);pair(30,0);pair(40,h);pair(1,s.replace(/[^\x20-\x7E]/g,'-'));};const circle=(x,y,r)=>{pair(0,'CIRCLE');pair(8,'OUTLINE');pair(10,x);pair(20,y);pair(30,0);pair(40,r);};let rect=(x,y,w,h)=>{line(x,y,x+w,y);line(x+w,y,x+w,y+h);line(x+w,y+h,x,y+h);line(x,y+h,x,y);};rect(0,0,297,210);text(12,193,'EVA PRINT SRL - '+m.application_examples[0].title.toUpperCase(),5);text(12,183,m.name,4);if(['gear','ring'].includes(m.drawing_type)){circle(75,110,40);circle(75,110,18);line(30,110,120,110,'CENTRE');line(75,65,75,155,'CENTRE');}else if(m.drawing_type==='bracket'){line(25,75,25,155);line(25,155,45,155);line(45,155,45,95);line(45,95,130,95);line(130,95,130,75);line(130,75,25,75);circle(35,135,4);circle(80,85,4);circle(115,85,4);}else{rect(25,75,100,80);rect(32,82,86,66);circle(30,80,2);circle(120,80,2);circle(30,150,2);circle(120,150,2);}rect(165,85,75,65);text(35,163,'FRONT VIEW');text(170,163,'TOP VIEW');line(25,62,125,62,'DIMENSIONS');line(25,58,25,70,'DIMENSIONS');line(125,58,125,70,'DIMENSIONS');text(65,55,'100 mm',3);line(0,35,297,35);text(12,25,'Original illustrative concept - not a manufacturing release',3);text(12,16,'Units: mm | Revision A | 2026-10-02 | Geometry schematic',3);text(12,8,'print@eva-org.com | '+m.id,2.5);pair(0,'ENDSEC');pair(0,'EOF');return p.join('\n')+'\n';}
for(const m of records){let dir='02_MATERIALS/'+m.id;await fs.mkdir(path.join(root,dir),{recursive:true});m.drawings={svg:'05_TECHNICAL_DRAWINGS/'+m.id+'.svg',png:'05_TECHNICAL_DRAWINGS/'+m.id+'.png',pdf:'05_TECHNICAL_DRAWINGS/'+m.id+'.pdf',dxf:'05_TECHNICAL_DRAWINGS/'+m.id+'.dxf',kind:'original_illustrative_concept'};await fs.writeFile(path.join(root,m.drawings.svg),drawing(m));await fs.writeFile(path.join(root,m.drawings.dxf),dxf(m));await fs.writeFile(path.join(root,dir,'material.json'),JSON.stringify(m,null,2));
let lines=[m.name,'',m.description_en,'','Advantages',...m.advantages.map(x=>'- '+x),'','Limitations and process requirements',...m.limitations.map(x=>'- '+x),'','Proposed application examples',...m.application_examples.map(x=>'- '+x.title+': '+x.description),'','Service status: '+m.service_status,'Stock: most material families are reported in stock by the owner; verify this exact grade and color.','', 'Technical characteristics',...m.properties.map(x=>'- '+x.property+': '+x.value+' [manufacturer webpage; specimen state not established]'),...Object.entries(m.settings).filter(([k,v])=>v&&k!=='source_url'&&k!=='values_are_grade_specific').map(([k,v])=>'- '+k+': '+v),'','Manufacturer technical data sheets',...m.datasheets.map(x=>'- '+x.document_type+' | '+x.path+' | '+x.url),m.manufacturer_tds_status==='downloaded'?'':'The manufacturer PDF for this exact grade was not found. Use the source product page and the clearly labelled EVA PRINT technical overview.','', 'Colors from manufacturer snapshot',...(m.colors.length?m.colors.map(x=>'- '+x):['See manufacturer product options; exact stock is not verified.']),'','Reference photographs',...m.reference_photos.map(x=>'- '+x.path+' | '+x.url+' | Reference only; publication permission not established.'),'','Original illustrative drawing: '+m.drawings.svg,'Source: '+m.source_url];await fs.writeFile(path.join(root,dir,'description.en.txt'),lines.filter(x=>x!==undefined).join('\n'));}
